#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps it reachable for GC; raw pointer was collected in packaged builds.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UArenaScoreTracker* without UPROPERTY, so the garbage collector does not see the reference and frees the object after ~1 minute; OnGoalScored then calls AddPoints on a dangling pointer (EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints). Fix: UPROPERTY() TObjectPtr<UArenaScoreTracker>.",
  "no_colors_cause": "DA_Primary palette is only referenced by a string path in LoadObject, so the cooker never packages /Game/Data/Palettes/DA_Primary (log: Couldn't find file for package /Game/Data/Palettes/DA_Primary); Palette is null and HUD falls back to gray. Fix: add /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
